export function valueTable(grindPerHour) {
  const rows = SHARK_CARDS.map((card) => {
    const perUsd = Math.round(card.gtaDollars / card.usd);
    const hoursSaved = grindPerHour > 0 ? card.gtaDollars / grindPerHour : 0;
    return {
      card,
      perUsd,
      usdPerMillion: Math.round(card.usd / (card.gtaDollars / 1e6) * 100) / 100,
      hoursSaved: Math.round(hoursSaved * 10) / 10,
      impliedWage: hoursSaved > 0 ? Math.round(card.usd / hoursSaved * 100) / 100 : 0
    };
  });
  const best = Math.max(...rows.map((r) => r.perUsd));
  return rows.map((r) => ({ ...r, best: r.perUsd === best }));
}
export function cheapestBundle(target) {
  const sorted = [...SHARK_CARDS].sort((a, b) => b.gtaDollars - a.gtaDollars);
  const cards = [];
  let total = 0;
  let guard = 0;
  while (total < target && guard++ < 200) {
    const next = [...sorted].reverse().find((c) => c.gtaDollars >= target - total) ?? sorted[0];
    cards.push(next);
    total += next.gtaDollars;
  }
  return {
    cards,
    usd: Math.round(cards.reduce((s, c) => s + c.usd, 0) * 100) / 100,
    gtaDollars: total
  };
}
export const money = (n) => `$${Math.round(n).toLocaleString("en-US")}`;
export const compactMoney = (n) => {
  const abs = Math.abs(n);
  if (abs >= 1e6)
    return `$${(n / 1e6).toFixed(abs >= 1e7 ? 0 : 2)}M`;
  if (abs >= 1000)
    return `$${Math.round(n / 1000)}K`;
  return `$${Math.round(n)}`;
};
